import AppLayout from '@/layouts/app-layout';
import Heading from '@/components/heading';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Head } from '@inertiajs/react';
import { useForm } from '@inertiajs/react';
import { Settings } from 'lucide-react';
import { dashboard } from '@/routes';
import { type BreadcrumbItem } from '@/types';

interface ThemeSettings {
    id: number;
    site_name: string;
    site_description: string | null;
    primary_color: string;
    secondary_color: string;
    logo_url: string | null;
}

interface SettingsProps {
    settings: ThemeSettings;
}

export default function ThemeSettings({ settings }: SettingsProps) {
    const breadcrumbs: BreadcrumbItem[] = [
        { title: 'Dashboard', href: dashboard().url },
        { title: 'Theme', href: '/admin/theme' },
        { title: 'Settings', href: '/admin/theme/settings' },
    ];

    const { data, setData, put, processing, errors } = useForm({
        site_name: settings.site_name || '',
        site_description: settings.site_description || '',
        primary_color: settings.primary_color || '#3b82f6',
        secondary_color: settings.secondary_color || '#10b981',
    });

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        put('/admin/theme/settings');
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="Theme Settings" />

            <div className="mx-auto max-w-7xl space-y-6">
                <Heading
                    title="Theme Settings"
                    description="Customize your site's basic settings and branding"
                />

                <Card>
                    <CardHeader>
                        <div className="flex items-center gap-2">
                            <Settings className="h-6 w-6" />
                            <CardTitle>Theme Settings</CardTitle>
                        </div>
                        <CardDescription>
                            Customize your site's basic settings and branding
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="space-y-2">
                                <Label htmlFor="site_name">Site Name</Label>
                                <Input
                                    id="site_name"
                                    value={data.site_name}
                                    onChange={(e) => setData('site_name', e.target.value)}
                                    placeholder="My Awesome Site"
                                />
                                {errors.site_name && (
                                    <p className="text-sm text-red-600">{errors.site_name}</p>
                                )}
                            </div>

                            <div className="space-y-2">
                                <Label htmlFor="site_description">Site Description</Label>
                                <Textarea
                                    id="site_description"
                                    value={data.site_description}
                                    onChange={(e) => setData('site_description', e.target.value)}
                                    placeholder="A brief description of your site..."
                                    rows={3}
                                />
                                {errors.site_description && (
                                    <p className="text-sm text-red-600">{errors.site_description}</p>
                                )}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label htmlFor="primary_color">Primary Color</Label>
                                    <div className="flex gap-2">
                                        <Input
                                            id="primary_color"
                                            type="color"
                                            value={data.primary_color}
                                            onChange={(e) => setData('primary_color', e.target.value)}
                                            className="w-20 h-10"
                                        />
                                        <Input
                                            value={data.primary_color}
                                            onChange={(e) => setData('primary_color', e.target.value)}
                                            placeholder="#3b82f6"
                                        />
                                    </div>
                                    {errors.primary_color && (
                                        <p className="text-sm text-red-600">{errors.primary_color}</p>
                                    )}
                                </div>

                                <div className="space-y-2">
                                    <Label htmlFor="secondary_color">Secondary Color</Label>
                                    <div className="flex gap-2">
                                        <Input
                                            id="secondary_color"
                                            type="color"
                                            value={data.secondary_color}
                                            onChange={(e) => setData('secondary_color', e.target.value)}
                                            className="w-20 h-10"
                                        />
                                        <Input
                                            value={data.secondary_color}
                                            onChange={(e) => setData('secondary_color', e.target.value)}
                                            placeholder="#10b981"
                                        />
                                    </div>
                                    {errors.secondary_color && (
                                        <p className="text-sm text-red-600">{errors.secondary_color}</p>
                                    )}
                                </div>
                            </div>

                            <div className="flex justify-end">
                                <Button type="submit" disabled={processing}>
                                    {processing ? 'Saving...' : 'Save Settings'}
                                </Button>
                            </div>
                        </form>
                    </CardContent>
                </Card>
            </div>
        </AppLayout>
    );
}
